+            ).map((input) => input.value);
+            return `${question.prompt} ${selected.length ? `→ ${selected.join(", ")}` : "→ no selections yet"}`;
+          });
+
+          status.textContent = `Submitted. ${answers.join(" | ")}`;
+        });
+
+        main.append(hero, form);
+        return main;
+      }
+
+      document.getElementById("app").appendChild(createApp());
+    </script>
+  </body>
+</html>
+

