   <body>
     <a class="skip-link" href="#main">Skip to main content</a>
     <div id="app"></div>

     <script>
       const quizData = [
         {
           id: "languages",
           prompt: "Which of these are programming languages?",
           help: "Choose all options that qualify as a programming language.",
           choices: [
             "Python",
             "HTML",
             "Java",
             "SQL",
           ],
         },
         {
           id: "paradigms",
           prompt: "Which of these are programming language paradigms?",
           choices: [
             "Object-oriented",
             "Functional",
             "Relational",
             "Procedural",
           ],
         },
         {
           id: "web",
           prompt: "Which of these are commonly used in web development?",
           choices: [
             "JavaScript",
             "TypeScript",
             "CSS",
             "Markdown",
           ],
         },
       ];

       function createChoice(questionId, choiceLabel, index) {
         const label = document.createElement("label");
         label.className = "choice";

         const input = document.createElement("input");
         input.type = "checkbox";
         input.name = questionId;
         input.value = choiceLabel;
         input.id = `${questionId}-${index}`;

         const text = document.createElement("span");
         text.textContent = choiceLabel;

         label.append(input, text);
         return label;
       }

       function createQuestion(question, index) {
         const wrapper = document.createElement("div");
         wrapper.className = "form-field";

         const fieldset = document.createElement("fieldset");

         const legend = document.createElement("legend");
         legend.textContent = `${index + 1}. ${question.prompt}`;

         fieldset.appendChild(legend);

         if (question.help) {
           const help = document.createElement("p");
           help.className = "help-text";
           help.id = `${question.id}-help`;
           help.textContent = question.help;
           fieldset.appendChild(help);
           fieldset.setAttribute("aria-describedby", help.id);
         }

         const group = document.createElement("div");
         group.className = "choices";

         question.choices.forEach((choiceLabel, choiceIndex) => {
           group.appendChild(createChoice(question.id, choiceLabel, choiceIndex));
         });

         fieldset.appendChild(group);
         wrapper.appendChild(fieldset);
         return wrapper;
       }

       function createApp() {
         const main = document.createElement("main");
         main.id = "main";
         main.className = "page";

         const hero = document.createElement("header");
         hero.className = "hero";

         const eyebrow = document.createElement("p");
         eyebrow.className = "eyebrow";
         eyebrow.textContent = "Interactive quiz";

         const title = document.createElement("h1");
         title.textContent = "Computer Languages Quiz";

         const lead = document.createElement("p");
         lead.className = "lead";
         lead.textContent = "A short 3-question quiz built with a React-style component structure and native form controls.";

         hero.append(eyebrow, title, lead);

         const form = document.createElement("form");
         form.noValidate = true;
         form.setAttribute("aria-describedby", "quiz-status");

         quizData.forEach((question, index) => {
           form.appendChild(createQuestion(question, index));
         });

         const actions = document.createElement("div");
         actions.className = "actions";

         const submit = document.createElement("button");
         submit.className = "submit-button";
         submit.type = "submit";
         submit.textContent = "Submit quiz";

         const status = document.createElement("p");
         status.className = "status";
         status.id = "quiz-status";
         status.setAttribute("aria-live", "polite");

         actions.append(submit, status);
         form.appendChild(actions);

         form.addEventListener("submit", (event) => {
           event.preventDefault();

           const answers = quizData.map((question) => {
             const selected = Array.from(
               form.querySelectorAll(`input[name="${question.id}"]:checked`)
             ).map((input) => input.value);
             return `${question.prompt} ${selected.length ? `→ ${selected.join(", ")}` : "→ no selections yet"}`;
           });

           status.textContent = `Submitted. ${answers.join(" | ")}`;
         });

         main.append(hero, form);
         return main;
       }

       document.getElementById("app").appendChild(createApp());
     </script>
   </body>
 </html>

